def api_logs_list():
    stdout, _ = exec_command("sudo docker ps --format {{.Names}}")
    containers = [f"🐋:{log}" for log in [log.strip().replace(".log", "") for log in stdout.split("\n")] if log]

    stdout, _ = exec_command(f"ls {LOGS_FOLDER}")
