 * Mirrors the backend tokenizer (`logs/query.py::tokenize`) so the chips the
 * user clicks match exactly the terms the server compiles.
 *
 * @param {string} text - Raw query text.
 * @returns {string[]} Terms in the order they were written.
 */
export function tokenizeQuery(text) {
  const source = text || ''
  const terms = []
  let current = ''
  let inQuotes = false
  let escaped = false

  for (const char of source) {
    if (escaped) {
      current += char
      escaped = false
      continue
    }
    if (char === '\\' && inQuotes) {
      current += char
      escaped = true
      continue
    }
    if (char === '"') {
      inQuotes = !inQuotes
      current += char
      continue
    }
    if (/\s/.test(char) && !inQuotes) {
      if (current) {
        terms.push(current)
        current = ''
      }
      continue
    }
    current += char
  }
  if (current) terms.push(current)
  return terms
}

