export function tokenizeQuery(text) {
  const source = text || ''
  const terms = []
  let current = ''
  let inQuotes = false
  let escaped = false

  for (const char of source) {
    if (escaped) {
      current += char
      escaped = false
      continue
    }
    if (char === '\\' && inQuotes) {
      current += char
      escaped = true
      continue
    }
    if (char === '"') {
      inQuotes = !inQuotes
      current += char
      continue
    }
    if (/\s/.test(char) && !inQuotes) {
      if (current) {
        terms.push(current)
        current = ''
      }
      continue
    }
    current += char
  }
  if (current) terms.push(current)
  return terms
