  // The interval and the debounce must never outlive the component that owns
  // them, otherwise a background tab keeps polling.
  if (getCurrentInstance()) {
    onBeforeUnmount(() => {
      destroyed = true
      stopLiveTail()
      cancelDebounce()
    })
