  return {
    // Filters
    sources,
    selectedSources,
    query,
    levels,
    timeRange,
    order,
    pageSize,
    histogramBuckets,
    // Results
    entries,
    total,
    page,
    hasMore,
    histogram,
    facets,
    stats,
    // Transport state
    loading,
    error,
    // Live tail
    liveTail,
    cursor,
    // Derived
    activeFilterCount,
    isLive,
    // Actions
    loadSources,
    runQuery,
    nextPage,
    prevPage,
    toggleLevel,
    clearLevels,
    setTimeRange,
    setOrder,
    setPageSize,
    zoomToBucket,
    setQuery,
    addFilterTerm,
    removeTermByIndex,
    clearQuery,
    toggleSource,
    setSources,
    reset,
    startLiveTail,
    stopLiveTail,
    toggleLiveTail,
    fetchEntry,
    fetchContext,
  }
}

