    // Filters
    sources,
    selectedSources,
    query,
    levels,
    minMs,
    activeQuickFilter,
    timeRange,
    order,
    pageSize,
    histogramBuckets,
    // Results
    entries,
    total,
    page,
    hasMore,
    histogram,
    facets,
    stats,
    // API analysis
    insights,
    insightsLoading,
    insightsError,
    // Transport state
