    prevPage,
    toggleLevel,
    clearLevels,
    setTimeRange,
    setOrder,
    setPageSize,
    zoomToBucket,
    setQuery,
    addFilterTerm,
    removeTermByIndex,
    clearQuery,
    toggleSource,
    setSources,
    reset,
    startLiveTail,
    stopLiveTail,
    toggleLiveTail,
    fetchEntry,
    fetchContext,
